import{_ as t,o,c as a,a2 as r}from"./chunks/framework.e4u2V5E7.js";const h=JSON.parse('{"title":"Html","description":"Html reference documentation","frontmatter":{"title":"Html","description":"Html reference documentation"},"headers":[],"relativePath":"knowledge/html.md","filePath":"knowledge/html.md","lastUpdated":1784485118000}'),i={name:"knowledge/html.md"};function n(d,e,c,s,l,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="html" tabindex="-1">Html <a class="header-anchor" href="#html" aria-label="Permalink to &quot;Html&quot;">​</a></h1><h1 id="semantic-html5-—-knowledge-reference" tabindex="-1">Semantic HTML5 — Knowledge Reference <a class="header-anchor" href="#semantic-html5-—-knowledge-reference" aria-label="Permalink to &quot;Semantic HTML5 — Knowledge Reference&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Reference for writing accessible, SEO-optimized, and maintainable HTML5. Covers semantic elements, accessibility attributes, forms, ARIA, microdata, Open Graph, meta tags, structured data, and progressive enhancement strategies.</p><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="semantic-html5-elements" tabindex="-1">Semantic HTML5 Elements <a class="header-anchor" href="#semantic-html5-elements" aria-label="Permalink to &quot;Semantic HTML5 Elements&quot;">​</a></h3><p>Semantic elements convey meaning to browsers, screen readers, and search engines. Use <code>&lt;header&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;aside&gt;</code>, <code>&lt;footer&gt;</code>, <code>&lt;figure&gt;</code>, <code>&lt;figcaption&gt;</code>, <code>&lt;time&gt;</code>, <code>&lt;address&gt;</code>, <code>&lt;details&gt;</code>, <code>&lt;summary&gt;</code>, <code>&lt;mark&gt;</code>, <code>&lt;progress&gt;</code>, <code>&lt;meter&gt;</code>.</p><h3 id="accessibility-attributes" tabindex="-1">Accessibility Attributes <a class="header-anchor" href="#accessibility-attributes" aria-label="Permalink to &quot;Accessibility Attributes&quot;">​</a></h3><p>Core ARIA attributes: <code>role</code>, <code>aria-label</code>, <code>aria-labelledby</code>, <code>aria-describedby</code>, <code>aria-hidden</code>, <code>aria-live</code>, <code>aria-expanded</code>, <code>aria-selected</code>, <code>aria-disabled</code>, <code>aria-required</code>. Use native HTML semantics first; ARIA supplements only when HTML semantics are insufficient.</p><h3 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h3><p>Proper form structure: <code>&lt;label&gt;</code> for every input, <code>type</code> attribute for input types, <code>required</code>/<code>pattern</code>/<code>minlength</code>/<code>maxlength</code> for validation, <code>&lt;fieldset&gt;</code> and <code>&lt;legend&gt;</code> for grouping, <code>autocomplete</code> for autofill, <code>name</code> for form submission.</p><h3 id="aria-accessible-rich-internet-applications" tabindex="-1">ARIA (Accessible Rich Internet Applications) <a class="header-anchor" href="#aria-accessible-rich-internet-applications" aria-label="Permalink to &quot;ARIA (Accessible Rich Internet Applications)&quot;">​</a></h3><p>ARIA roles, states, and properties bridge gaps where HTML semantics are insufficient. <code>role=&quot;dialog&quot;</code>, <code>aria-modal=&quot;true&quot;</code> for modals. <code>role=&quot;tablist&quot;</code>/<code>role=&quot;tab&quot;</code>/<code>role=&quot;tabpanel&quot;</code> for tabs. <code>aria-live=&quot;polite&quot;</code> for dynamic content updates. First rule: don&#39;t use ARIA if native HTML works.</p><h3 id="microdata" tabindex="-1">Microdata <a class="header-anchor" href="#microdata" aria-label="Permalink to &quot;Microdata&quot;">​</a></h3><p>Schema.org vocabulary embedded in HTML via <code>itemscope</code>, <code>itemtype</code>, and <code>itemprop</code> attributes. Structured data for search engines: products, articles, events, recipes, organizations. Largely superseded by JSON-LD for most use cases.</p><h3 id="open-graph-protocol" tabindex="-1">Open Graph Protocol <a class="header-anchor" href="#open-graph-protocol" aria-label="Permalink to &quot;Open Graph Protocol&quot;">​</a></h3><p>Meta tags for social media sharing: <code>og:title</code>, <code>og:description</code>, <code>og:image</code>, <code>og:url</code>, <code>og:type</code>, <code>og:site_name</code>. Essential for link previews on Facebook, LinkedIn, and other platforms that read OG tags.</p><h3 id="meta-tags" tabindex="-1">Meta Tags <a class="header-anchor" href="#meta-tags" aria-label="Permalink to &quot;Meta Tags&quot;">​</a></h3><p><code>&lt;meta charset=&quot;UTF-8&quot;&gt;</code> for encoding. <code>&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;</code> for responsive design. <code>&lt;meta name=&quot;description&quot;&gt;</code> for SEO. <code>&lt;meta name=&quot;robots&quot;&gt;</code> for crawler directives. <code>&lt;meta http-equiv=&quot;X-UA-Compatible&quot;&gt;</code> for IE compatibility.</p><h3 id="structured-data-json-ld" tabindex="-1">Structured Data (JSON-LD) <a class="header-anchor" href="#structured-data-json-ld" aria-label="Permalink to &quot;Structured Data (JSON-LD)&quot;">​</a></h3><p>JSON-LD in <code>&lt;script type=&quot;application/ld+json&quot;&gt;</code> provides structured data to search engines. Enables rich snippets: breadcrumbs, FAQs, how-tos, events, products. Google&#39;s structured data testing tool validates markup.</p><h3 id="progressive-enhancement" tabindex="-1">Progressive Enhancement <a class="header-anchor" href="#progressive-enhancement" aria-label="Permalink to &quot;Progressive Enhancement&quot;">​</a></h3><p>Build a baseline experience that works without JavaScript, then enhance with JavaScript. Use server-rendered HTML for core content. JavaScript enhances interactivity. CSS provides visual presentation. This ensures resilience and accessibility.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Use native HTML elements before ARIA</strong> — <code>&lt;button&gt;</code> is always better than <code>&lt;div role=&quot;button&quot;&gt;</code>; native elements provide built-in keyboard handling and semantics</li><li><strong>Always associate labels with inputs</strong> — <code>&lt;label for=&quot;email&quot;&gt;Email&lt;/label&gt;&lt;input id=&quot;email&quot;&gt;</code> ensures screen readers announce the label and clicking the label focuses the input</li><li><strong>Use <code>&lt;main&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code> on every page</strong> — landmark elements allow screen reader users to jump between sections</li><li><strong>Set <code>lang</code> attribute on <code>&lt;html&gt;</code></strong> — <code>&lt;html lang=&quot;ar&quot; dir=&quot;rtl&quot;&gt;</code> or <code>&lt;html lang=&quot;en&quot;&gt;</code> enables correct screen reader pronunciation and hyphenation</li><li><strong>Use <code>alt</code> text for all meaningful images</strong> — decorative images get <code>alt=&quot;&quot;</code> (empty); informative images describe the content</li><li><strong>Implement proper heading hierarchy</strong> — <code>&lt;h1&gt;</code> through <code>&lt;h6&gt;</code> should form a logical outline; never skip levels for styling</li><li><strong>Use <code>aria-live</code> regions for dynamic content</strong> — <code>aria-live=&quot;polite&quot;</code> announces updates without interrupting the user; use for status messages and form feedback</li><li><strong>Add <code>&lt;meta name=&quot;viewport&quot;&gt;</code> to every page</strong> — without it, mobile browsers render at desktop width; never disable user scaling</li></ol><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ol><li><strong>Using <code>&lt;div&gt;</code> and <code>&lt;span&gt;</code> for everything</strong> — loses all semantic meaning; screen readers cannot navigate or announce content correctly</li><li><strong>Using <code>tabindex</code> values greater than 0</strong> — positive tabindex disrupts natural tab order; use <code>tabindex=&quot;0&quot;</code> for focusable non-interactive elements or <code>tabindex=&quot;-1&quot;</code> for programmatic focus</li><li><strong>Hiding content with <code>display: none</code> instead of <code>aria-hidden</code></strong> — both hide content, but <code>aria-hidden</code> hides from screen readers while keeping visual presence</li><li><strong>Using <code>alt</code> text as keyword stuffing</strong> — search engines penalize; alt text should describe the image accurately and concisely</li><li><strong>Ignoring keyboard navigation</strong> — all interactive elements must be operable with keyboard alone; test by tabbing through the page</li><li><strong>Using color alone to convey meaning</strong> — add text labels, icons, or patterns; color-blind users cannot distinguish colors alone</li><li><strong>Not providing focus indicators</strong> — removing <code>outline</code> without replacement breaks keyboard navigation; always ensure visible focus states</li><li><strong>Using <code>&lt;br&gt;</code> for layout spacing</strong> — use CSS margins/padding for spacing; <code>&lt;br&gt;</code> is for line breaks within text content only</li></ol><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ol><li><strong>Missing <code>lang</code> attribute</strong> — screen readers default to English pronunciation; always set the correct language</li><li><strong>Images without <code>alt</code> attributes</strong> — screen readers announce the file name, which is meaningless; always provide descriptive alt text</li><li><strong>Empty <code>&lt;a href=&quot;#&quot;&gt;</code> links</strong> — non-functional links confuse keyboard users; use <code>&lt;button&gt;</code> for actions</li><li><strong>Using <code>&lt;i&gt;</code> or <code>&lt;b&gt;</code> instead of <code>&lt;em&gt;</code> or <code>&lt;strong&gt;</code></strong> — semantic emphasis vs visual styling; use <code>&lt;em&gt;</code> for stress emphasis and <code>&lt;strong&gt;</code> for importance</li><li><strong>Forms without labels</strong> — screen readers cannot announce what input the user is filling; always use <code>&lt;label&gt;</code> or <code>aria-label</code></li><li><strong>Missing <code>type</code> on <code>&lt;button&gt;</code></strong> — defaults to <code>submit</code>, which can trigger form submission unexpectedly; always set explicit <code>type</code></li><li><strong>Not using <code>&lt;time datetime=&quot;&quot;&gt;</code></strong> — machine-readable dates enable search engines and assistive technology to parse dates correctly</li><li><strong>Ignoring document outline</strong> — poor heading structure makes content navigation impossible for screen reader users</li></ol><h2 id="decision-guidelines" tabindex="-1">Decision Guidelines <a class="header-anchor" href="#decision-guidelines" aria-label="Permalink to &quot;Decision Guidelines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Approach</th></tr></thead><tbody><tr><td>Page-level landmarks</td><td><code>&lt;main&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;header&gt;</code>, <code>&lt;footer&gt;</code>, <code>&lt;aside&gt;</code></td></tr><tr><td>Content grouping</td><td><code>&lt;article&gt;</code>, <code>&lt;section&gt;</code></td></tr><tr><td>Interactive controls</td><td>Native <code>&lt;button&gt;</code>, <code>&lt;input&gt;</code>, <code>&lt;select&gt;</code></td></tr><tr><td>Custom widgets</td><td>ARIA roles + keyboard handlers</td></tr><tr><td>Dynamic updates</td><td><code>aria-live</code> regions</td></tr><tr><td>SEO structured data</td><td>JSON-LD in <code>&lt;script type=&quot;application/ld+json&quot;&gt;</code></td></tr><tr><td>Social sharing</td><td>Open Graph meta tags</td></tr><tr><td>Responsive images</td><td><code>&lt;picture&gt;</code> + <code>&lt;source&gt;</code> + <code>&lt;img&gt;</code> with <code>srcset</code></td></tr><tr><td>Form validation</td><td>HTML5 validation attributes + custom JS for complex cases</td></tr><tr><td>Internationalization</td><td><code>lang</code> attribute + <code>dir</code> attribute + <code>&lt;meta charset&gt;</code></td></tr></tbody></table><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/HTML" target="_blank" rel="noreferrer">MDN HTML Reference</a></li><li><a href="https://www.w3.org/WAI/ARIA/apd/" target="_blank" rel="noreferrer">WAI-ARIA Authoring Practices</a></li><li><a href="https://schema.org" target="_blank" rel="noreferrer">Schema.org</a></li><li><a href="https://ogp.me" target="_blank" rel="noreferrer">Open Graph Protocol</a></li><li><a href="https://webaim.org" target="_blank" rel="noreferrer">WebAIM Accessibility Resources</a></li></ul><h2 id="practical-notes" tabindex="-1">Practical Notes <a class="header-anchor" href="#practical-notes" aria-label="Permalink to &quot;Practical Notes&quot;">​</a></h2><ul><li>HTML is the most accessible and resilient layer of the web stack; invest in solid HTML before adding CSS/JavaScript</li><li>Use the <code>HTMLHint</code> VS Code extension for real-time HTML validation</li><li>Google&#39;s Rich Results Test validates structured data for search engine compatibility</li><li>Always test with keyboard-only navigation (unplug your mouse) and a screen reader (NVDA/VoiceOver)</li><li><code>&lt;template&gt;</code> elements are inert and do not render; use for client-side rendering patterns without JavaScript framework overhead</li><li><code>&lt;dialog&gt;</code> element provides native modal behavior with <code>&lt;dialog&gt;.showModal()</code> and <code>::backdrop</code> pseudo-element</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/knowledge/">Knowledge Base</a> for all reference documents.</p>',37)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
